// Support ticket MCP server.
// Implements a single tool, ticket_create, with strict input validation,
// stable sequential ticket ids, and clear errors for invalid input or
// unknown tools.

const PRIORITIES = new Set(['low', 'normal', 'high']);

const TICKET_CREATE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['title', 'description'],
  properties: {
    title: { type: 'string', minLength: 1 },
    description: { type: 'string', minLength: 1 },
    priority: { type: 'string', enum: ['low', 'normal', 'high'] },
  },
};

// Stable, process-wide counter so ids restart at t1 on a fresh load and
// otherwise monotonically increment across calls.
let ticketCounter = 0;

function nextTicketId() {
  ticketCounter += 1;
  return `t${ticketCounter}`;
}

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function validateTicketCreateArguments(args) {
  if (!isPlainObject(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  for (const key of Object.keys(TICKET_CREATE_SCHEMA.properties)) {
    if (!(key in args)) continue;
    const def = TICKET_CREATE_SCHEMA.properties[key];
    const value = args[key];
    if (def.type === 'string') {
      if (typeof value !== 'string') {
        throw new Error(`Invalid arguments: '${key}' must be a string`);
      }
      if (def.minLength !== undefined && value.length < def.minLength) {
        throw new Error(`Invalid arguments: '${key}' must not be empty`);
      }
    }
  }

  for (const required of TICKET_CREATE_SCHEMA.required) {
    const value = args[required];
    if (typeof value !== 'string' || value.length === 0) {
      throw new Error(`Invalid arguments: '${required}' is required and must be a non-empty string`);
    }
  }

  if ('priority' in args) {
    if (typeof args.priority !== 'string' || !PRIORITIES.has(args.priority)) {
      throw new Error(`Invalid arguments: 'priority' must be one of low, normal, high`);
    }
  }

  for (const key of Object.keys(args)) {
    if (!(key in TICKET_CREATE_SCHEMA.properties)) {
      throw new Error(`Invalid arguments: unknown field '${key}'`);
    }
  }
}

export async function listTools() {
  return [
    {
      name: 'ticket_create',
      description: 'Create a new support ticket and return its id.',
      inputSchema: TICKET_CREATE_SCHEMA,
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'ticket_create') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const safeArgs = args && typeof args === 'object' ? args : {};
  validateTicketCreateArguments(safeArgs);

  const priority = safeArgs.priority ?? 'normal';
  const id = nextTicketId();
  const title = safeArgs.title;

  const text = `Created ticket ${id} (priority: ${priority}): ${title}`;
  return { content: [{ type: 'text', text }] };
}

