assert.match(threw, /Unknown tool/);

// empty title
try { await callTool('ticket_create', {title:'',description:'x'}); assert.fail('should throw'); }
catch (e) { assert.match(e.message, /title/); }

// missing description
try { await callTool('ticket_create', {title:'x'}); assert.fail('should throw'); }
